开发任务：给待办列表增加按状态筛选
当前代码（demo/todo/store.mjs#listTodos, demo/todo/store.mjs#filterByStatus, demo/todo/store.mjs#countByStatus）：
```js
// 示例业务工程：待办清单（内存存储，供 SDD 模块改造与测试）
let seq = 0;
const rows = [];

export function addTodo(title, status = "pending") {
  if (!title) throw new Error("title 必填");
  const item = { id: ++seq, title, status };
  rows.push(item);
  return { ...item };
}

export function listTodos() {
  return rows.map((r) => ({ ...r }));
}

// 目标功能：按状态筛选，保持创建顺序。当前未实现，目标测试应先失败。
export function filterByStatus(/* status */) {
  throw new Error("filterByStatus 未实现");
}

export function countByStatus(status) {
  return rows.filter((r) => r.status === status).length;
}

```
适用的规格（由 seekdb 向量检索得到）：
【规格 01-列表与筛选】待办清单 - 列表与筛选规格
- S1：列表展示全部待办，按创建顺序返回，调用方拿到的副本不应影响内部存储。 - S2：支持按状态筛选，状态只允许 `pending` 与 `done`；筛选结果保持原有创建顺序。 - S3：状态筛选必须复用同一份存储数据，不得重置或复制数据源。 - S7：同一筛选条件可重复调用，结果稳定且不改变存储内容；非法状态返回空数组而不是抛错。
距离=0.664

【规格 02-计数与兼容】待办清单 - 计数与兼容规格
- S4：`countByStatus(status)` 返回指定状态条目数，未知状态返回 0。 - S5：新增待办时未传状态默认 `pending`；`title` 为空时抛出错误。 - S6：筛选与计数不得改变既有条目字段（`id`、`title`、`status`）。
距离=0.885
目标测试（当前失败原因即 filterByStatus 未实现）：
```js
import { test } from "node:test";
import assert from "node:assert/strict";
import { addTodo, filterByStatus } from "../store.mjs";

// 目标测试：改前应因 filterByStatus 未实现而失败；改造后应全部通过。
test("目标：按状态筛选只返回匹配项并保持创建顺序", () => {
  addTodo("A-pending", "pending");
  addTodo("B-done", "done");
  addTodo("C-pending", "pending");
  const pending = filterByStatus("pending");
  assert.deepEqual(pending.map((x) => x.title).slice(-2), ["A-pending", "C-pending"]);
  assert.equal(pending.every((x) => x.status === "pending"), true);
  assert.equal(filterByStatus("done").every((x) => x.status === "done"), true);
});

```
请给出实现。

